    if ((previous == NULL) || (current == NULL) || (rate_t_s == NULL)) {
        return ADCS_E_NULL;
    }

    if (!isfinite(previous->x) || !isfinite(previous->y) || !isfinite(previous->z) ||
        !isfinite(current->x) || !isfinite(current->y) || !isfinite(current->z) ||
        !isfinite(previous_time_s) || !isfinite(current_time_s)) {
        rate_t_s->x = 0.0;
        rate_t_s->y = 0.0;
        rate_t_s->z = 0.0;
        return ADCS_E_RANGE;
    }

    double dt = current_time_s - previous_time_s;

    if (!isfinite(dt) || dt <= 0.0) {
        rate_t_s->x = 0.0;
        rate_t_s->y = 0.0;
        rate_t_s->z = 0.0;
        return ADCS_E_RANGE;
    }

    rate_t_s->x = (current->x - previous->x) / dt;
    rate_t_s->y = (current->y - previous->y) / dt;
    rate_t_s->z = (current->z - previous->z) / dt;

    return ADCS_OK;
}

